S      <- 1:6
p5     <- length(which(S == 5)) / length(S)          # {5}
peven  <- length(which(S %% 2 == 0)) / length(S)     # {2,4,6}
# 5 and "even" share no faces -> disjoint -> just add
p5_or_even <- p5 + peven
round(c(p5 = p5, p_even = peven, p5_or_even = p5_or_even), 4)

